const notes = new Map();
let counter = 0;

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          body: { type: 'string' }
        },
        required: ['title', 'body'],
        additionalProperties: false
      }
    },
    {
      name: 'note_get',
      description: 'Get a note by id',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string' }
        },
        required: ['note_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const { title, body } = args;
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof body !== 'string' || body.trim() === '') {
      throw new Error('body must be a non-empty string');
    }
    counter += 1;
    const id = `n${counter}`;
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id}: ${title}` }]
    };
  }
  if (name === 'note_get') {
    const { note_id } = args;
    if (typeof note_id !== 'string' || note_id.trim() === '') {
      throw new Error('note_id must be a non-empty string');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Note ${note_id} not found`);
    }
    return {
      content: [{ type: 'text', text: `${note.title}\n\n${note.body}` }]
    };
  }
  throw new Error(`Unknown tool: ${name}`);
}
